            return int(p[0]), int(p[1])
        if isinstance(p, dict):
            if "position" in p and isinstance(p["position"], (list, tuple)) and len(p["position"]) >= 2:
                return int(p["position"][0]), int(p["position"][1])
            if "x" in p and "y" in p:
                return int(p["x"]), int(p["y"])
        return None

