    for p in obstacles:
        q = norm_point(p)
        if q is not None:
            x, y = q
            if 0 <= x < w and 0 <= y < h:
                obs.add((x, y))

    res = []
    for p in resources:
        q = norm_point(p)
        if q is not None:
            x, y = q
            if 0 <= x < w and 0 <= y < h:
                res.append((x, y))

    if not res:
        return [0, 0]

